import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays, getLastDayOfMonth } from './dates.js';

function isValidDiscountPercent(value) {
  return typeof value === 'number' && value >= 0 && value <= 100;
}

/**
 * Create a draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }} params
 * @returns {import('./result.js').Result<{ customerId: string, issueDate: string, status: string, terms: string, dueDate: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }>}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate and set terms
  const validTerms = ['NET14', 'NET30', 'EOM'];
  if (!validTerms.includes(terms)) {
    return fail('TERMS_INVALID');
  }

  // Calculate due date based on terms
  let dueDate;
  if (terms === 'NET14') {
    dueDate = addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    dueDate = addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    dueDate = getLastDayOfMonth(issueDate);
  }

  // Validate lines array is not empty
  if (!lines || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Validate issueDate
  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  // Check customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) {
    return fail('CUSTOMER_NOT_FOUND');
  }

  const customer = customerResult.value;

  // Validate and enrich lines
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Validate discountPercent if provided
    if (line.discountPercent !== undefined && !isValidDiscountPercent(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    // Get product from catalogue
    const productResult = getProduct(line.sku);
    if (!productResult.ok) {
      return fail('UNKNOWN_SKU');
    }

    const product = productResult.value;
    const enrichedLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    // Determine discount: explicit discountPercent wins, otherwise use tier discount
    if (line.discountPercent !== undefined) {
      // Use the explicit discount (even if 0)
      if (line.discountPercent > 0) {
        enrichedLine.discountPercent = line.discountPercent;
      }
    } else {
      // Apply tier discount if not explicitly set
      const tierDiscount = TIER_DISCOUNTS[customer.tier];
      if (tierDiscount > 0) {
        enrichedLine.discountPercent = tierDiscount;
      }
    }

    enrichedLines.push(enrichedLine);
  }

  // Return the invoice
  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    terms,
    dueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

/**
 * Calculate the total for a single invoice line.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} Total in cents
 */
export function lineTotal(line) {
  return roundCents(line.qty * line.unitPrice);
}

/**
 * Calculate the totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }} All in cents, never below 0
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);

  const discount = invoice.lines.reduce((sum, line) => {
    const lineDiscount = roundCents((lineTotal(line) * (line.discountPercent || 0)) / 100);
    return sum + lineDiscount;
  }, 0);

  const vat = invoice.lines.reduce((sum, line) => {
    const lineTot = lineTotal(line);
    const lineDiscount = roundCents((lineTot * (line.discountPercent || 0)) / 100);
    const lineAfterDiscount = lineTot - lineDiscount;
    const lineVAT = roundCents((lineAfterDiscount * line.vatRate) / 100);
    return sum + lineVAT;
  }, 0);

  const voucher = invoice.voucher?.amount || 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);

  return {
    subtotal,
    discount,
    vat,
    voucher,
    total,
  };
}

/**
 * Add or update a line on a draft invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} line
 * @returns {import('./result.js').Result}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Validate discountPercent if provided
  if (discountPercent !== undefined && !isValidDiscountPercent(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  // Get product from catalogue
  const productResult = getProduct(sku);
  if (!productResult.ok) {
    return fail('UNKNOWN_SKU');
  }

  const product = productResult.value;

  // Copy lines and check if SKU already exists
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex !== -1) {
    // Update existing line
    newLines[existingLineIndex].qty += qty;
    // If discountPercent is provided, update it; otherwise keep existing
    if (discountPercent !== undefined) {
      newLines[existingLineIndex].discountPercent = discountPercent;
    }
  } else {
    // Add new line
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    if (discountPercent !== undefined) {
      newLine.discountPercent = discountPercent;
    }

    newLines.push(newLine);
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {import('./result.js').Result}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Find the line to remove
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) {
    return fail('LINE_NOT_FOUND');
  }

  // Check if it's the last line
  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  // Create new invoice without that line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice by assigning it a number and changing status to 'issued'.
 * @param {{ customerId: string, issueDate: string, status: string, terms: string, dueDate: string, lines: Array }} invoice
 * @param {string[]} existingNumbers Array of invoice numbers already issued
 * @returns {import('./result.js').Result}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    number,
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    terms: invoice.terms,
    dueDate: invoice.dueDate,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
  });
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ status: string, voucher?: { code: string, amount: number } }} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {import('./result.js').Result}
 */
export function applyVoucher(invoice, { code, amount }) {
  // Check status is 'draft'
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Check if voucher already exists
  if (invoice.voucher) {
    return fail('VOUCHER_EXISTS');
  }

  // Validate amount
  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  // Create new invoice with voucher
  const newInvoice = {
    ...invoice,
    voucher: { code, amount },
  };

  return ok(newInvoice);
}

